#include "MultiDictionary.h"
#include "Unicode.h"
#include <iostream>
#include <limits>
#include <string>
struct Lang{const char*code;const char*name;const char*path;};
int main(){const Lang a[]={{"te","Telugu (తెలుగు)","data/te.txt"},{"ta","Tamil (தமிழ்)","data/ta.txt"},{"hi","Hindi (हिन्दी)","data/hi.txt"}};std::cout<<"=== Multilingual Unicode Autocorrect ===\n1. Telugu (తెలుగు)\n2. Tamil (தமிழ்)\n3. Hindi (हिन्दी)\nChoose language [1-3]: ";int n=0;if(!(std::cin>>n)||n<1||n>3){std::cerr<<"Invalid selection.\n";return 2;}std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');auto l=a[n-1];spell::MultiDictionary d;if(!d.load(l.path)){std::cerr<<"Missing "<<l.path<<". Run python scripts/fetch_dictionaries.py\n";return 1;}std::cout<<l.name<<" dictionary loaded ("<<d.size()<<" words). Type :quit to exit.\n";std::string w;while(std::cout<<"\nWord> "&&std::getline(std::cin,w)){w=spell::normalizeWord(w);if(w==":quit"||w==":q")break;if(w.empty())continue;if(!spell::isSupportedScript(w,l.code)){std::cout<<"Input does not match the selected script.\n";continue;}if(d.contains(w)){std::cout<<"Correct: "<<w<<"\n";continue;}auto s=d.suggest(w,5,2);if(s.empty()){std::cout<<"No close matches found.\n";continue;}std::cout<<"Suggestions:\n";for(size_t i=0;i<s.size();i++)std::cout<<" "<<i+1<<". "<<s[i].word<<" (distance "<<s[i].distance<<")\n";std::cout<<"Choose 1-"<<s.size()<<" to autocorrect, 0 to keep: ";int k=0;if(!(std::cin>>k)){std::cin.clear();std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');continue;}std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');if(k>0&&(size_t)k<=s.size())std::cout<<"Autocorrect: "<<s[k-1].word<<"\n";else std::cout<<"Kept: "<<w<<"\n";}return 0;}